+func TestTransactionalReloadRollsBackAndPersistsOutcome(t *testing.T) {
+	dir := t.TempDir()
+	configFile := filepath.Join(dir, "prometheus.yml")
+	if err := os.WriteFile(configFile, []byte("global:\
  external_labels:\
    version: new\
"), 0o644); err != nil {
+		t.Fatal(err)
+	}
+	goodFile := filepath.Join(dir, "good.yml")
+	if err := os.WriteFile(goodFile, []byte("global:\
  external_labels:\
    version: old\
"), 0o644); err != nil {
+		t.Fatal(err)
+	}
+
+	logger := promslog.NewNopLogger()
+	r := newTransactionalReloader(dir, logger)
+	if _, err := os.Stat(filepath.Join(dir, reloadStatusFilename)); !errors.Is(err, os.ErrNotExist) {
+		t.Fatalf("status file exists before a reload attempt: %v", err)
+	}
+	good, err := loadReloadConfig(goodFile, false, logger)
+	if err != nil {
+		t.Fatal(err)
+	}
+	r.setLastGood(good)
+
+	var calls []string
+	label := func(confVersion string) func(*config.Config) error {
+		return func(cfg *config.Config) error {
+			calls = append(calls, confVersion+":"+string(cfg.GlobalConfig.ExternalLabels["version"]))
+			return nil
+		}
+	}
+	first := reloader{name: "first", reloader: func(cfg *config.Config) error {
+		calls = append(calls, "first:"+string(cfg.GlobalConfig.ExternalLabels["version"]))
+		return nil
+	}}
+	second := reloader{name: "second", reloader: func(cfg *config.Config) error {
+		calls = append(calls, "second:"+string(cfg.GlobalConfig.ExternalLabels["version"]))
+		if cfg.GlobalConfig.ExternalLabels["version"] == "new" {
+			return errors.New("apply failed")
+		}
+		return nil
+	}}
+	_ = label // Keep the call assertions below focused on reloader names.
+
+	if err := r.reload(configFile, false, logger, &safePromQLNoStepSubqueryInterval{}, func(bool) {}, first, second); err == nil {
+		t.Fatal("expected reload to fail")
+	}
+	status := r.Status()
+	if status.ErrorCategory != "apply_error" || !status.RollbackAttempted || !status.RollbackSuccessful || status.FailedReloader != "second" {
+		t.Fatalf("unexpected status: %#v", status)
+	}
+	if len(status.AppliedReloaders) != 1 || status.AppliedReloaders[0] != "first" {
+		t.Fatalf("unexpected applied reloaders: %#v", status.AppliedReloaders)
+	}
+	if len(calls) != 4 || calls[0] != "first:new" || calls[1] != "second:new" || calls[2] != "first:old" || calls[3] != "second:old" {
+		t.Fatalf("unexpected reloader calls: %#v", calls)
+	}
+	if _, err := os.Stat(filepath.Join(dir, reloadStatusFilename)); err != nil {
+		t.Fatalf("status file was not persisted: %v", err)
+	}
+
+	restored := newTransactionalReloader(dir, logger).Status()
+	if restored.LastReloadID != status.LastReloadID || restored.ErrorCategory != "apply_error" {
+		t.Fatalf("persisted status was not restored: %#v", restored)
+	}
+}
+
+func TestTransactionalReloadIgnoresCorruptPersistedStatus(t *testing.T) {
