+const reloadStatusFilename = "reload-status.json"
+
+type transactionalReloader struct {
+	mu       sync.RWMutex
+	status   api_v1.ReloadStatus
+	lastGood *config.Config
+	path     string
+	logger   *slog.Logger
+}
+
+func newTransactionalReloader(storagePath string, logger *slog.Logger) *transactionalReloader {
+	r := &transactionalReloader{
+		status: defaultReloadStatus(),
+		path:   filepath.Join(storagePath, reloadStatusFilename),
+		logger: logger,
+	}
+	data, err := os.ReadFile(r.path)
+	if err != nil {
+		return r
+	}
+	var status api_v1.ReloadStatus
+	if err := json.Unmarshal(data, &status); err != nil || !validReloadStatus(status) {
+		logger.Warn("Ignoring invalid persisted reload status", "path", r.path, "err", err)
+		return r
+	}
+	r.status = normalizeReloadStatus(status)
+	return r
+}
+
+func defaultReloadStatus() api_v1.ReloadStatus {
+	return api_v1.ReloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
+}
+
+func validReloadStatus(status api_v1.ReloadStatus) bool {
+	switch status.ErrorCategory {
+	case "none", "load_error", "apply_error", "rollback_error":
+		return true
+	default:
+		return false
+	}
+}
+
+func normalizeReloadStatus(status api_v1.ReloadStatus) api_v1.ReloadStatus {
+	if status.AppliedReloaders == nil {
+		status.AppliedReloaders = []string{}
+	}
+	if status.ReloaderTimingsMS == nil {
+		status.ReloaderTimingsMS = map[string]float64{}
+	}
+	return status
+}
+
+func (r *transactionalReloader) Status() api_v1.ReloadStatus {
+	r.mu.RLock()
+	defer r.mu.RUnlock()
+	status := r.status
+	status.AppliedReloaders = append([]string(nil), status.AppliedReloaders...)
+	status.ReloaderTimingsMS = make(map[string]float64, len(r.status.ReloaderTimingsMS))
+	for k, v := range r.status.ReloaderTimingsMS {
+		status.ReloaderTimingsMS[k] = v
+	}
+	return status
+}
+
+func (r *transactionalReloader) setLastGood(conf *config.Config) {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	r.lastGood = conf
+}
+
+func (r *transactionalReloader) reload(filename string, enableExemplarStorage bool, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, callback func(bool), rls ...reloader) (err error) {
+	start := time.Now()
+	logger.Info("Loading configuration file", "filename", filename)
+	status := defaultReloadStatus()
+	status.LastReloadID = start.UTC().Format(time.RFC3339Nano)
+
+	defer func() {
+		if err == nil {
+			configSuccess.Set(1)
+			configSuccessTime.SetToCurrentTime()
+			callback(true)
+		} else {
+			configSuccess.Set(0)
+			callback(false)
+		}
+		r.record(status)
+	}()
+
+	conf, err := loadReloadConfig(filename, enableExemplarStorage, logger)
+	if err != nil {
+		status.ErrorCategory = "load_error"
+		status.ErrorMessage = err.Error()
+		return err
+	}
+
+	for _, rl := range rls {
+		rstart := time.Now()
+		applyErr := rl.reloader(conf)
+		status.ReloaderTimingsMS[rl.name] = float64(time.Since(rstart)) / float64(time.Millisecond)
+		if applyErr != nil {
+			status.ErrorCategory = "apply_error"
+			status.ErrorMessage = applyErr.Error()
+			status.FailedReloader = rl.name
+			logger.Error("Failed to apply configuration", "reloader", rl.name, "err", applyErr)
+			if len(status.AppliedReloaders) > 0 {
+				status.RollbackAttempted = true
+				if rollbackErr := r.rollback(rls); rollbackErr != nil {
+					status.ErrorCategory = "rollback_error"
+					status.ErrorMessage = fmt.Sprintf("applying %s failed: %v; rollback failed: %v", rl.name, applyErr, rollbackErr)
+				} else {
+					status.RollbackSuccessful = true
+				}
+			}
+			return fmt.Errorf("error applying configuration with reloader %q: %w", rl.name, applyErr)
+		}
+		status.AppliedReloaders = append(status.AppliedReloaders, rl.name)
+	}
+
+	updateGoGC(conf, logger)
+	noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
+	r.setLastGood(conf)
+	status.LastReloadSuccessful = true
+	logger.Info("Completed loading of configuration file", "filename", filename, "totalDuration", time.Since(start))
+	return nil
+}
+
+func (r *transactionalReloader) rollback(rls []reloader) error {
+	r.mu.RLock()
+	lastGood := r.lastGood
+	r.mu.RUnlock()
+	if lastGood == nil {
+		return fmt.Errorf("no last known-good configuration available")
+	}
+	for _, rl := range rls {
+		if err := rl.reloader(lastGood); err != nil {
+			return fmt.Errorf("reloader %q: %w", rl.name, err)
+		}
+	}
+	return nil
+}
+
+func (r *transactionalReloader) record(status api_v1.ReloadStatus) {
+	r.mu.Lock()
+	r.status = normalizeReloadStatus(status)
+	data, err := json.Marshal(r.status)
+	if err == nil {
+		tmp := r.path + ".tmp"
+		err = os.WriteFile(tmp, data, 0o644)
+		if err == nil {
+			err = os.Rename(tmp, r.path)
+		}
+	}
+	r.mu.Unlock()
+	if err != nil {
+		r.logger.Warn("Failed to persist reload status", "path", r.path, "err", err)
+	}
+}
